      _loc1_.animation_mc.animation.play();
   }
   _loc1_.SA._visible = true;
   _loc1_.SA_PLAY._visible = false;
   _loc1_.SA_PAUSE._visible = false;
   _loc1_.EA._visible = false;
   _loc2_.spanSound = false;
}

on(release){
   _global.Play = true;
   _global.Pause = false;
   _global.CompClick = "";
   _global.quizSection = false;
   _global.gSound.stop();
   _root.SA._visible = true;
   _root.EA._visible = false;
   _global.spanSound = false;
   _root.loadSWFMovie();
}

on(press){
   _global.playaction = false;
   _global.Play = true;
   _global.Pause = false;
   _global.CompClick = "";
   _global.quizSection = false;
   _global.gSound.stop();
   _root.SA._visible = true;
   _root.EA._visible = false;
   _global.spanSound = false;
   if(_root.animation_mc.animation._currentframe <= 1)
   {
      _root.doPlayPreviousMovie();
   }
   _root.animation_mc.animation.start = true;
   _global.rewind = 1;
}
